import type { SdgnMissionQcm } from "./sdgnMissionQcmBank";

/** Banque officielle du DS SDGN Première (100 QCM). */
export const SDGN_DS_PREMIERE_QCM: SdgnMissionQcm[] = [
  { id: "sdgn-p-ds-01", chapter: 1, difficulte: "difficile", question: "Un candidat, paralysé par le stress, perd ses mots en entretien. Le recruteur en déduit immédiatement qu'il manque d'intelligence.", choix: ["C'est un biais de personnalité, car l'émotion du moment fausse la sélection des signaux par l'observateur.", "C'est un biais de personnalité, car le manque d'intelligence est un trait de caractère inné et permanent.", "C'est un biais de perception, car l'émotion du moment fausse la sélection et l'interprétation des signaux par l'observateur.", "C'est un biais de perception, car le manque d'intelligence est un trait de caractère inné et permanent."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-02", chapter: 1, difficulte: "difficile", question: "Le DRH refuse systématiquement les CV des jeunes de banlieue, affirmant : \"Ils ne respectent jamais l'autorité\".", choix: ["Il utilise un stéréotype, car il exprime une émotion négative isolée face à un individu.", "Il utilise un stéréotype, car il applique une croyance réductrice à l'ensemble d'un groupe social.", "Il exprime un préjugé, car il exprime une émotion négative isolée face à un individu.", "Il exprime un préjugé, car il applique une croyance réductrice à l'ensemble d'un groupe social."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-03", chapter: 1, difficulte: "difficile", question: "Un employé refuse les nouvelles méthodes informatiques car il éprouve une profonde aversion acquise au fil des années envers la technologie.", choix: ["C'est sa personnalité, qui constitue une prédisposition évaluative (cognitive et affective) envers un objet précis.", "C'est sa personnalité, qui englobe des traits de caractère innés et stables (introversion, extraversion).", "C'est son attitude, qui constitue une prédisposition évaluative (cognitive et affective) envers un objet précis.", "C'est son attitude, qui englobe des traits de caractère innés et stables (introversion, extraversion)."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-04", chapter: 1, difficulte: "difficile", question: "Pour valider l'embauche d'un pilote, la compagnie aérienne exige la présentation de sa licence de vol réglementaire.", choix: ["Elle vérifie sa compétence, car la licence prouve sa capacité à mobiliser des savoirs en situation réelle.", "Elle vérifie sa compétence, car la licence constitue une reconnaissance institutionnelle sur le marché du travail.", "Elle vérifie sa qualification, car la licence prouve sa capacité à mobiliser des savoirs en situation réelle.", "Elle vérifie sa qualification, car la licence constitue une reconnaissance institutionnelle sur le marché du travail."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-05", chapter: 1, difficulte: "difficile", question: "Dans le service des achats, tout le monde porte un jean le vendredi et utilise l'acronyme \"ASAP\" à la fin de chaque phrase.", choix: ["Ce sont des normes, car ce sont des règles écrites imposées par le règlement intérieur.", "Ce sont des normes, car ce sont des signes informels de reconnaissance propres au groupe.", "Ce sont des codes, car ce sont des règles écrites imposées par le règlement intérieur.", "Ce sont des codes, car ce sont des signes informels de reconnaissance propres au groupe."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-06", chapter: 1, difficulte: "difficile", question: "Un groupe d'employés de différents services se regroupe secrètement chaque midi pour organiser la création d'un syndicat.", choix: ["C'est un groupe d'appartenance formel, institué par l'organigramme de l'organisation.", "C'est un groupe d'appartenance formel, fondé sur des affinités ou convictions personnelles.", "C'est un groupe d'appartenance informel, institué par l'organigramme de l'organisation.", "C'est un groupe d'appartenance informel, fondé sur des affinités ou convictions personnelles."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-07", chapter: 1, difficulte: "difficile", question: "Un jeune stagiaire imite la façon de parler et de s'habiller des cadres supérieurs, espérant intégrer le comité de direction dans dix ans.", choix: ["Les cadres sont son groupe d'appartenance, dont il copie les comportements idéalisés.", "Les cadres sont son groupe d'appartenance, dont il subit la supervision directe.", "Les cadres sont son groupe de référence, dont il copie les comportements idéalisés pour y être intégré.", "Les cadres sont son groupe de référence, dont il subit la supervision directe."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-08", chapter: 1, difficulte: "difficile", question: "L'opérateur de saisie doit désormais non seulement taper les factures, mais aussi contrôler leur légalité et valider les paiements (hausse de la réflexion).", choix: ["C'est un élargissement des tâches, car le nombre de tâches augmente au même niveau d'exécution.", "C'est un élargissement des tâches, car le niveau d'autonomie et de responsabilité intellectuelle augmente.", "C'est un enrichissement des tâches, car le nombre de tâches augmente au même niveau d'exécution.", "C'est un enrichissement des tâches, car le niveau d'autonomie et de responsabilité intellectuelle augmente."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-09", chapter: 1, difficulte: "difficile", question: "Face à un client hurlant au téléphone, le conseiller clientèle reste silencieux, ne s'énerve pas et reprend le protocole d'assistance.", choix: ["Il utilise son empathie, ce qui lui permet de réguler ses propres émotions dans une situation stressante.", "Il utilise son empathie, ce qui lui permet de ressentir précisément l'émotion du client.", "Il utilise son contrôle de soi, ce qui lui permet de réguler ses propres émotions dans une situation stressante.", "Il utilise son contrôle de soi, ce qui lui permet de ressentir précisément l'émotion du client."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-10", chapter: 1, difficulte: "difficile", question: "Le salaire brut d'un employé est de 3 000 €. Les cotisations salariales sont de 600 € et les cotisations patronales de 1 200 €.", choix: ["Le coût global du travail est de 4 200 € (Salaire brut + cotisations patronales).", "Le coût global du travail est de 4 800 € (Salaire brut + cotisations patronales + cotisations salariales).", "Le coût global du travail est de 3 600 € (Salaire net + cotisations patronales).", "Le coût global du travail est de 3 000 € (Salaire brut uniquement)."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-11", chapter: 1, difficulte: "difficile", question: "L'entreprise \"PrimeA\" verse 500 € à chaque vendeur qui dépasse la vente de 50 contrats dans le mois.", choix: ["C'est une rémunération de base (fixe), visant à sécuriser financièrement l'acteur.", "C'est une rémunération de base (fixe), visant à lier l'intérêt matériel de l'acteur aux objectifs de l'organisation.", "C'est une incitation (variable), visant à sécuriser financièrement l'acteur.", "C'est une incitation (variable), visant à lier l'intérêt matériel de l'acteur aux objectifs de l'organisation."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-12", chapter: 1, difficulte: "difficile", question: "Le dirigeant écoute les avis de ses collaborateurs en réunion, mais prend systématiquement la décision finale seul.", choix: ["Son style de direction est participatif, car il consulte l'équipe tout en gardant le pouvoir.", "Son style de direction est participatif, car le pouvoir décisionnel est totalement décentralisé.", "Son style de direction est consultatif, car il consulte l'équipe tout en gardant le pouvoir.", "Son style de direction est consultatif, car le pouvoir décisionnel est totalement décentralisé."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-13", chapter: 1, difficulte: "difficile", question: "Un chef d'équipe, sans charisme, obtient l'obéissance de ses subordonnés uniquement en les menaçant de blâmes.", choix: ["Son pouvoir repose sur son leadership, assis sur son influence informelle et personnelle.", "Son pouvoir repose sur son leadership, assis sur son statut hiérarchique et légal.", "Son pouvoir repose sur son autorité, assise sur son influence informelle et personnelle.", "Son pouvoir repose sur son autorité, assise sur son statut hiérarchique et légal."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-14", chapter: 1, difficulte: "difficile", question: "L'entreprise confie la paie de ses employés à un cabinet d'expertise comptable indépendant.", choix: ["C'est une flexibilité quantitative externe (ajustement des effectifs précaires).", "C'est une flexibilité quantitative externe (polyvalence interne).", "C'est une externalisation, consistant à déléguer une tâche périphérique à un tiers pour se recentrer sur son métier.", "C'est une externalisation, consistant à ajuster les horaires de travail des salariés."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-15", chapter: 1, difficulte: "difficile", question: "Pour répondre à une forte demande en été, le supermarché recrute 30 étudiants en CDD.", choix: ["L'entreprise recourt à la flexibilité fonctionnelle (polyvalence des salariés internes).", "L'entreprise recourt à la flexibilité fonctionnelle (ajustement rapide des effectifs externes).", "L'entreprise recourt à la flexibilité quantitative externe (polyvalence des salariés internes).", "L'entreprise recourt à la flexibilité quantitative externe (ajustement rapide des effectifs externes)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-16", chapter: 1, difficulte: "difficile", question: "Les syndicats lancent une grève pour exiger une augmentation des salaires de 5 %, la direction la refuse pour préserver les dividendes.", choix: ["Il s'agit d'un conflit de valeurs, portant sur l'éthique de l'entreprise.", "Il s'agit d'un conflit de valeurs, portant sur la répartition de la richesse créée.", "Il s'agit d'un conflit d'intérêts, portant sur l'éthique de l'entreprise.", "Il s'agit d'un conflit d'intérêts, portant sur la répartition de la richesse créée."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-17", chapter: 1, difficulte: "difficile", question: "Un litige éclate entre deux services. Le directeur refuse de s'en mêler en espérant que la situation se tasse.", choix: ["Il opte pour un mode de résolution par dépassement.", "Il opte pour un mode de résolution par recours hiérarchique.", "Il opte pour un mode de résolution par compromis.", "Il opte pour une gestion par évitement."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-18", chapter: 1, difficulte: "difficile", question: "Lors d'un débat houleux, un collaborateur présente des tableaux statistiques pour justifier son budget.", choix: ["Il utilise l'influence affective, cherchant à prouver objectivement ses dires.", "Il utilise l'influence affective, s'appuyant sur le registre des émotions (peur, séduction).", "Il utilise l'argumentation logique, cherchant à prouver objectivement ses dires.", "Il utilise l'argumentation logique, s'appuyant sur le registre des émotions (peur, séduction)."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-19", chapter: 1, difficulte: "difficile", question: "L'identité numérique d'un individu ou d'une organisation correspond théoriquement à :", choix: ["L'image globale et la réputation que les autres internautes se font de lui.", "L'ensemble exhaustif des traces numériques (volontaires ou involontaires) laissées sur Internet.", "La protection juridique imposée par le RGPD.", "Le code source de son site internet."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-20", chapter: 1, difficulte: "difficile", question: "Un salarié critique publiquement son entreprise sur Twitter. La DRH le sanctionne.", choix: ["Il a menacé l'identité numérique de l'entreprise, en brouillant la frontière vie privée / vie professionnelle.", "Il a menacé l'identité numérique de l'entreprise, en détruisant sa valeur boursière.", "Il a menacé l'e-réputation de l'entreprise, en brouillant la frontière vie privée / vie professionnelle.", "Il a menacé l'e-réputation de l'entreprise, en détruisant sa valeur boursière."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-21", chapter: 1, difficulte: "difficile", question: "Le \"taux de rotation\" (turnover) de l'entreprise atteint les 40 %. Cet indicateur RH traduit :", choix: ["Une forte flexibilité fonctionnelle positive.", "Une hausse de la productivité du travail.", "Un dysfonctionnement social (mauvais climat) générant des coûts cachés de recrutement.", "Une baisse mécanique des cotisations patronales obligatoires."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-22", chapter: 1, difficulte: "difficile", question: "Le document officiel qui décrit précisément les missions, l'autonomie et le positionnement hiérarchique d'un acteur est :", choix: ["Le contrat de travail.", "La fiche de poste.", "Le bilan social.", "L'organigramme général."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-23", chapter: 1, difficulte: "difficile", question: "La productivité du travail d'une équipe se mesure par le rapport entre :", choix: ["Les bénéfices nets et le chiffre d'affaires.", "La quantité (ou valeur) produite et les moyens humains mobilisés (effectifs ou heures).", "Le salaire brut total et les cotisations sociales.", "Les moyens humains mobilisés et la valeur ajoutée globale."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-24", chapter: 1, difficulte: "difficile", question: "L'aménagement de locaux confortables, d'horaires flexibles et d'une conciergerie d'entreprise illustre une démarche axée sur :", choix: ["L'enrichissement des tâches.", "La flexibilité quantitative interne.", "La Qualité de Vie au Travail (QVT) pour améliorer le bien-être.", "L'élargissement des qualifications."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-25", chapter: 1, difficulte: "difficile", question: "Les rites, les mythes et les valeurs partagées (ex: fêter chaque succès en sonnant une cloche) forment :", choix: ["L'identité numérique de l'entreprise.", "La culture de l'organisation, cimentant le sentiment d'appartenance.", "La structure formelle d'autorité.", "Le cadre de l'ajustement mutuel externe."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-26", chapter: 2, difficulte: "difficile", question: "Un tableau Excel brut affiche le nombre \"5000\" sans en-tête ni unité.", choix: ["C'est une information, car sa numérisation la rend exploitable pour l'action.", "C'est une information, car c'est un fait brut objectif et non interprété.", "C'est une donnée, car sa numérisation la rend exploitable pour l'action.", "C'est une donnée, car c'est un fait brut objectif et non interprété."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-27", chapter: 2, difficulte: "difficile", question: "Le système précise que \"5000\" correspond au \"Nombre de clients perdus en mai\".", choix: ["Cet élément devient une information, car il a été traité et contextualisé pour avoir du sens.", "Cet élément devient une information, car il a été chiffré sur une Blockchain.", "Cet élément devient une donnée, car il a été traité et contextualisé pour avoir du sens.", "Cet élément devient une donnée, car il a été chiffré sur une Blockchain."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-28", chapter: 2, difficulte: "difficile", question: "Un site web exige l'adresse IP et la date de naissance de ses visiteurs pour l'inscription.", choix: ["Il collecte des données ouvertes (Open Data), soumises au règlement RGPD.", "Il collecte des données ouvertes (Open Data), exemptées du règlement RGPD.", "Il collecte des données à caractère personnel, soumises au règlement RGPD.", "Il collecte des données à caractère personnel, exemptées du règlement RGPD."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-29", chapter: 2, difficulte: "difficile", question: "La métropole de Paris publie gratuitement en ligne les coordonnées GPS de tous ses lampadaires pour les développeurs d'applications.", choix: ["Elle s'inscrit dans une démarche de Big Data, pour stimuler l'innovation civile.", "Elle s'inscrit dans une démarche de Big Data, pour protéger la vie privée.", "Elle s'inscrit dans une démarche d'Open Data, pour stimuler l'innovation civile.", "Elle s'inscrit dans une démarche d'Open Data, pour protéger la vie privée."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-30", chapter: 2, difficulte: "difficile", question: "Netflix croise les historiques de visionnage, les arrêts sur image et les clics de millions d'usagers pour anticiper le succès d'une série.", choix: ["L'entreprise exploite l'Open Data, basé sur des algorithmes prédictifs massifs.", "L'entreprise exploite l'Open Data, basé sur la transparence gouvernementale.", "L'entreprise exploite le Big Data (mégadonnées), basé sur des algorithmes prédictifs massifs.", "L'entreprise exploite le Big Data (mégadonnées), basé sur la transparence gouvernementale."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-31", chapter: 2, difficulte: "difficile", question: "Une validation de commande en caisse met instantanément à jour le stock, le compte bancaire et l'alerte livraison dans toute l'entreprise.", choix: ["Ce système est un Réseau Pair-à-Pair, qui garantit l'unicité de la base de données.", "Ce système est un Réseau Pair-à-Pair, qui cloisonne l'information en silos.", "Ce système est un PGI (Progiciel de Gestion Intégré), qui garantit l'unicité de la base de données.", "Ce système est un PGI (Progiciel de Gestion Intégré), qui cloisonne l'information en silos."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-32", chapter: 2, difficulte: "difficile", question: "L'encyclopédie Wikipédia est rédigée, corrigée et mise à jour par une multitude d'internautes inconnus.", choix: ["C'est l'illustration de l'Intelligence Artificielle, la coopération générant une valeur ajoutée.", "C'est l'illustration de l'Intelligence Artificielle, un algorithme fonctionnant en autonomie.", "C'est l'illustration de l'Intelligence Collective, la coopération générant une valeur ajoutée supérieure.", "C'est l'illustration de l'Intelligence Collective, un algorithme fonctionnant en autonomie."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-33", chapter: 2, difficulte: "difficile", question: "Une marque de soda lance un concours mondial sur le web pour que les consommateurs créent le nouveau design de sa canette.", choix: ["Elle pratique le Crowdfunding, externalisant une tâche créative vers la foule.", "Elle pratique le Crowdfunding, levant des fonds auprès du public.", "Elle pratique le Crowdsourcing, externalisant une tâche créative vers la foule.", "Elle pratique le Crowdsourcing, levant des fonds auprès du public."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-34", chapter: 2, difficulte: "difficile", question: "Une entreprise cesse d'acheter des disques durs locaux et loue le stockage de ses fichiers sur des serveurs distants via Internet.", choix: ["Elle opte pour l'Intranet, gagnant en mobilité mais s'exposant à une dépendance au réseau Internet.", "Elle opte pour l'Intranet, réduisant la mobilité mais sécurisant ses données.", "Elle opte pour le Cloud Computing, gagnant en mobilité mais s'exposant à une dépendance au réseau Internet.", "Elle opte pour le Cloud Computing, réduisant la mobilité mais sécurisant ses données."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-35", chapter: 2, difficulte: "difficile", question: "En gestion des organisations, un \"processus\" se définit théoriquement comme :", choix: ["Un enchaînement d'activités logiques et structurées mobilisant des acteurs pour atteindre un objectif précis.", "Un algorithme mathématique de tri des Mégadonnées.", "Un document juridique détaillant la politique d'Open Data.", "Le matériel physique hébergeant le système d'information."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-36", chapter: 2, difficulte: "difficile", question: "Le parcours numérisé d'un devis passe automatiquement du commercial au chef des ventes, puis à la comptabilité.", choix: ["C'est un PGI, qui trace et automatise la chaîne des étapes d'une tâche.", "C'est un PGI, qui limite la communication à un seul département.", "C'est un Workflow (flux de travaux), qui trace et automatise la chaîne des étapes d'une tâche.", "C'est un Workflow (flux de travaux), qui limite la communication à un seul département."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-37", chapter: 2, difficulte: "difficile", question: "Le déploiement d'un Réseau Social d'Entreprise (RSE) au sein des services vise managérialement à :", choix: ["Centraliser exclusivement la communication descendante du PDG.", "Vendre les invendus de l'entreprise sur des places de marché.", "Casser les silos hiérarchiques et favoriser la communication transversale informelle.", "Sécuriser les données selon les règles strictes du RGPD."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-38", chapter: 2, difficulte: "difficile", question: "L'intelligence artificielle d'un cabinet comptable saisit et impute automatiquement 10 000 factures en une nuit.", choix: ["L'effet est la création d'une rigidité totale, bloquant toute intervention.", "L'effet est la publication involontaire des données en Open Data.", "L'effet est la suppression immédiate de l'expertise humaine stratégique.", "L'effet est la modification de l'activité, libérant l'acteur des tâches routinières pour se concentrer sur l'analyse."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-39", chapter: 2, difficulte: "difficile", question: "L'implémentation d'un nouveau logiciel impose aux employés de saisir les données dans un format rigide, interdisant toute autre méthode de travail.", choix: ["Le SI génère ici de l'agilité organisationnelle, modélisant la méthode de travail.", "Le SI génère ici de l'agilité organisationnelle, favorisant l'improvisation.", "Le SI génère ici de la rigidité organisationnelle, le paramétrage contraignant l'action.", "Le SI génère ici de la rigidité organisationnelle, favorisant l'improvisation."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-40", chapter: 2, difficulte: "difficile", question: "Pour aller plus vite, un salarié utilise son compte \"Google Drive\" personnel pour héberger des contrats confidentiels, sans en informer le service informatique.", choix: ["Il utilise le BYOD, renforçant la cybersécurité.", "Il utilise le BYOD, détruisant la valeur partenariale.", "Il utilise le Shadow IT, créant une vulnérabilité critique et une perte de contrôle des données.", "Il utilise l'Open Data, créant une vulnérabilité critique et une perte de contrôle des données."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-41", chapter: 2, difficulte: "difficile", question: "La \"Transformation Numérique\" (ou digitale) d'une entreprise se caractérise fondamentalement par :", choix: ["Le remplacement complet du matériel informatique obsolète par des tablettes.", "Une mutation globale de ses processus, de son organisation et de son modèle économique par l'intégration des technologies digitales.", "La fermeture de ses usines physiques au profit de la sous-traitance.", "L'abandon du compte de résultat au profit du bilan social."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-42", chapter: 2, difficulte: "difficile", question: "Une faille de sécurité externe provoque le vol et la diffusion des mots de passe de millions de clients.", choix: ["L'entreprise viole le principe de l'Open Data, risquant une forte amende.", "L'entreprise viole le principe de l'Open Data, améliorant paradoxalement son agilité.", "L'entreprise viole le RGPD, risquant de lourdes sanctions financières et la destruction de sa valeur perçue.", "L'entreprise viole le RGPD, améliorant paradoxalement son agilité."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-43", chapter: 2, difficulte: "difficile", question: "Contrairement au site web institutionnel ouvert à tout public, l'Intranet est un outil de :", choix: ["E-communication commerciale, visant à capter l'attention de nouveaux prospects.", "E-communication interne, offrant un réseau privé et sécurisé réservé aux seuls membres de l'organisation.", "Big Data, visant à capter l'attention de nouveaux prospects.", "Big Data, offrant un réseau privé et sécurisé réservé aux seuls membres de l'organisation."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-44", chapter: 2, difficulte: "difficile", question: "L'utilisation par un salarié de son propre smartphone (personnel) pour accéder au réseau de l'entreprise s'appelle le :", choix: ["Cloud Computing, favorisant la mobilité mais posant un défi majeur de sécurisation.", "Cloud Computing, réduisant la mobilité mais garantissant la sécurité.", "BYOD (Bring Your Own Device), favorisant la mobilité mais posant un défi majeur de sécurisation.", "BYOD (Bring Your Own Device), réduisant la mobilité mais garantissant la sécurité."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-45", chapter: 2, difficulte: "difficile", question: "Un algorithme d'affectation universitaire refuse un élève. La loi impose la \"transparence des algorithmes\", signifiant que :", choix: ["Le code source de l'algorithme doit être publié en Open Data mondial.", "L'administration doit pouvoir expliquer en langage clair les critères et la pondération ayant conduit l'IA à prendre cette décision.", "Les données de l'élève doivent être anonymisées et stockées sur le Cloud.", "L'administration doit confier le traitement à une intelligence collective."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-46", chapter: 2, difficulte: "difficile", question: "La \"e-communication\" globale d'une organisation contemporaine englobe :", choix: ["L'intégration de l'ensemble des flux numérisés (réseaux sociaux, site, intranet) à destination des publics internes et externes.", "L'intégration de l'ensemble des flux numérisés à destination exclusive des partenaires financiers externes.", "L'unique utilisation des courriels pour les tâches de supervision.", "La publication en ligne du bilan comptable."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-47", chapter: 2, difficulte: "difficile", question: "Le rôle premier et structurel d'un Système d'Information (SI) est de :", choix: ["Mesurer la rentabilité boursière de l'entreprise en temps réel.", "Collecter, stocker, traiter et diffuser l'information pertinente pour coordonner l'action et éclairer la décision.", "Remplacer les ressources humaines par des systèmes experts.", "Protéger les salariés des risques psychosociaux (RPS)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-48", chapter: 2, difficulte: "difficile", question: "Une boutique physique lance une application mobile permettant l'achat en ligne et le retrait en magasin (\"Click & Collect\").", choix: ["Cette digitalisation crée de la rigidité, la boutique devenant incompatible avec le web.", "Cette digitalisation crée de l'agilité, l'ouverture de nouveaux canaux permettant de s'adapter aux comportements des clients.", "Cette digitalisation supprime le principe de la marge commerciale.", "Cette digitalisation supprime la valeur partenariale de l'entreprise."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-49", chapter: 2, difficulte: "difficile", question: "L'installation de capteurs connectés (IoT) sur des moteurs d'avion permet à l'entreprise de :", choix: ["Créer un Intranet local déconnecté.", "Produire de la donnée en temps réel permettant de réaliser de la maintenance prédictive (nouveau service).", "Vendre les données personnelles des pilotes en Open Data.", "Supprimer l'autorité hiérarchique au sein de l'organisation."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-50", chapter: 2, difficulte: "difficile", question: "Une attaque de \"Ransomware\" (rançongiciel) paralyse l'entreprise en cryptant ses bases de données clients contre de l'argent.", choix: ["Le pilier de la \"Transparence\" algorithmique est rompu.", "Le pilier de la \"Rentabilité financière\" algorithmique est rompu.", "Le pilier de la \"Disponibilité\" (et de l'intégrité) de l'information est violé.", "Le pilier de la \"Traçabilité\" de l'information est violé."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-51", chapter: 3, difficulte: "difficile", question: "L'entreprise a généré 1 000 000 € de Chiffre d'Affaires. Elle a acheté pour 300 000 € de matières et payé 400 000 € de salaires.", choix: ["La Valeur Ajoutée (VA) s'élève à 300 000 € (CA - Achats - Salaires).", "La Valeur Ajoutée (VA) s'élève à 700 000 € (CA - Achats de matières).", "Le Résultat Net s'élève à 700 000 € (CA - Achats de matières).", "Le Résultat Net s'élève à 1 000 000 € (équivalent au CA)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-52", chapter: 3, difficulte: "difficile", question: "Dans un magasin de vêtements, la Marge Commerciale d'un article se calcule par :", choix: ["Le Prix de Vente HT moins les charges de loyer et d'électricité.", "Le Prix de Vente HT moins le Coût d'Achat HT des marchandises vendues.", "Le Chiffre d'Affaires total moins la Valeur Ajoutée.", "Le Chiffre d'Affaires total moins l'Impôt sur les sociétés."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-53", chapter: 3, difficulte: "difficile", question: "L'Impôt sur les Sociétés (IS) payé par l'entreprise représente une fraction de la Valeur Ajoutée distribuée à :", choix: ["L'autofinancement.", "L'État et aux collectivités.", "L'actionnariat privé.", "L'URSSAF (organismes sociaux)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-54", chapter: 3, difficulte: "difficile", question: "La part de la richesse que l'entreprise décide de conserver en réserves plutôt que de la distribuer est appelée :", choix: ["Le dividende, garantissant les capacités d'investissement futures de l'organisation.", "Le dividende, rémunérant le risque pris par les apporteurs de capitaux.", "L'autofinancement, garantissant les capacités d'investissement futures de l'organisation.", "L'autofinancement, rémunérant le risque pris par les apporteurs de capitaux."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-55", chapter: 3, difficulte: "difficile", question: "Dans le processus de répartition de la richesse créée (VA), le versement d'intérêts rémunère :", choix: ["L'État, au titre des services publics rendus.", "Les prêteurs (banques), au titre des capitaux externes prêtés.", "Les actionnaires, au titre du risque boursier.", "Les salariés, au titre de leur participation à la production."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-56", chapter: 3, difficulte: "difficile", question: "Le document comptable qui dresse la photographie du \"Patrimoine\" de l'entreprise (ce qu'elle possède à l'actif et ce qu'elle doit au passif) à un instant T est :", choix: ["Le Compte de Résultat.", "Le Bilan.", "Le Tableau de bord.", "Le Bilan Social."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-57", chapter: 3, difficulte: "difficile", question: "Le document comptable qui retrace l'activité de l'année pour expliquer la formation du bénéfice ou de la perte (Produits - Charges) est :", choix: ["Le Compte de Résultat.", "Le Bilan.", "Le Tableau de bord.", "Le Bilan Social."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-58", chapter: 3, difficulte: "difficile", question: "Lors d'une AG, les actionnaires exigent une hausse des dividendes. Simultanément, les syndicats exigent que ces bénéfices financent une augmentation de salaire.", choix: ["C'est un conflit de répartition de la Valeur Ajoutée entre acteurs aux intérêts opposés.", "C'est un conflit d'ajustement mutuel entre acteurs aux intérêts convergents.", "C'est la preuve de l'harmonie inhérente au processus de rentabilité.", "C'est la preuve de l'inutilité du compte de résultat."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-59", chapter: 3, difficulte: "difficile", question: "La \"Rentabilité financière\" d'une organisation se mesure techniquement par le ratio comparant :", choix: ["Le bénéfice net et le chiffre d'affaires.", "Le bénéfice net et les capitaux propres apportés par les associés.", "Le chiffre d'affaires et l'endettement.", "L'actif total et le passif total."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-60", chapter: 3, difficulte: "difficile", question: "La \"Profitabilité\" d'une organisation se mesure techniquement par le ratio comparant :", choix: ["Le bénéfice net et le chiffre d'affaires (Marge nette).", "Le bénéfice net et les capitaux propres apportés par les associés.", "Le chiffre d'affaires et l'endettement.", "L'actif total et le passif total."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-61", chapter: 3, difficulte: "difficile", question: "L'indicateur synthétique de performance commerciale qui mesure le poids des ventes d'une entreprise par rapport aux ventes totales de son marché s'appelle :", choix: ["La rentabilité commerciale.", "Le seuil d'écrémage.", "La Marge brute.", "La Part de marché."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-62", chapter: 3, difficulte: "difficile", question: "Un petit restaurant obtient la note maximale sur Google Avis, saluant la décoration et le service.", choix: ["Il consolide sa valeur financière, ce qui réduira ses coûts de matières premières.", "Il consolide sa valeur financière, ce qui stimulera sa performance commerciale.", "Il consolide sa valeur perçue (e-réputation), ce qui réduira ses coûts de matières premières.", "Il consolide sa valeur perçue (e-réputation), ce qui stimulera sa performance commerciale (hausse des clients)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-63", chapter: 3, difficulte: "difficile", question: "Une association (loi 1901) a pour mission de financer la recherche contre le cancer grâce aux dons.", choix: ["Sa performance est exclusivement commerciale, évaluée par les dons récoltés.", "Sa performance est exclusivement financière, évaluée par l'atteinte stricte de l'équilibre budgétaire.", "Sa performance est globale : elle est avant tout sociale (mission remplie) sous l'exigence d'une contrainte financière (équilibre budgétaire).", "Sa performance est globale : elle est avant tout commerciale (mission remplie) sous l'exigence d'une contrainte d'Open Data."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-64", chapter: 3, difficulte: "difficile", question: "Une mairie avait pour objectif de rénover 3 ponts avec 300 000 €. Elle rénove les 3 ponts mais dépense 400 000 €.", choix: ["L'action publique a été inefficace (budget dépassé) mais efficiente (objectif atteint).", "L'action publique a été inefficace (objectif atteint) mais efficiente (gaspillage de ressources).", "L'action publique a été efficace (budget dépassé) mais inefficiente (objectif atteint).", "L'action publique a été efficace (objectif atteint) mais inefficiente (gaspillage des deniers publics)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-65", chapter: 3, difficulte: "difficile", question: "Le \"Bilan Social\" est une obligation légale pour les entreprises françaises de plus de 300 salariés. Il regroupe :", choix: ["Des indicateurs sur l'empreinte carbone et les rejets polluants (performance environnementale).", "Des indicateurs sur la rentabilité boursière des investissements (performance financière).", "Des indicateurs quantitatifs sur l'emploi, les rémunérations, les conditions de santé et la formation (performance sociale).", "Des indicateurs sur l'ensemble des dépenses publicitaires (performance commerciale)."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-66", chapter: 3, difficulte: "difficile", question: "Le \"Tableau de bord\" de gestion tire son utilité quotidienne pour le manager du fait qu'il :", choix: ["Centralise toutes les données brutes du PGI en listant l'intégralité des factures émises.", "Remplace légalement le Bilan financier face à l'administration fiscale.", "Sélectionne et synthétise un nombre restreint d'indicateurs clés (KPI), mis à jour rapidement pour alerter sur un écart et guider le pilotage.", "Synthétise exclusivement les données financières de l'année N-5."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-67", chapter: 3, difficulte: "difficile", question: "Un constructeur automobile et un fabricant de puces électroniques collaborent depuis 10 ans, co-financent la recherche et sécurisent leurs approvisionnements exclusifs. Quel type de valeur cela crée-t-il ?", choix: ["Une valeur financière spéculative, fondée sur la coopération stratégique.", "Une valeur partenariale, actif immatériel puissant fondé sur la stabilité, la confiance et la coopération stratégique entre acteurs de la chaîne.", "Une valeur sociale, fondée sur la coopération stratégique.", "Une valeur perçue, actif immatériel puissant fondé sur la stabilité, la confiance et la coopération stratégique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-68", chapter: 3, difficulte: "difficile", question: "Un fabricant de sacs fait produire ses modèles pour 40 € et les revend 800 € en boutique, justifiant ce prix par le prestige absolu de sa marque dans le monde entier.", choix: ["L'écart de prix s'appuie sur l'efficience de la Supply Chain.", "L'écart de prix s'appuie sur la valeur financière, liée à la cotation boursière du produit.", "L'écart de prix s'appuie sur la valeur perçue, liée à l'image de marque et à la désirabilité immatérielle du produit.", "L'écart de prix s'appuie sur la valeur sociale, liée à l'image de marque et à la désirabilité immatérielle du produit."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-69", chapter: 3, difficulte: "difficile", question: "Si, sur un marché hautement concurrentiel, le prix de vente est bloqué par les clients mais que l'entreprise subit une violente inflation du coût de ses matières premières, elle subit :", choix: ["Un effet d'aubaine, la hausse des charges réduisant sa marge commerciale.", "Un effet de levier, la hausse des charges non répercutée écrasant sa rentabilité.", "Un effet de ciseau, la hausse des charges non répercutée écrasant mécaniquement sa marge bénéficiaire unitaire.", "Une augmentation mécanique de la valeur de ses immobilisations au bilan."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-70", chapter: 3, difficulte: "difficile", question: "La notion contemporaine de \"Performance Globale\" impose à l'entreprise de ne plus se focaliser uniquement sur l'économie, mais d'équilibrer :", choix: ["Ses résultats sur les piliers économique (profit), social (conditions de travail) et environnemental (écologie) dans une approche systémique (RSE).", "Ses résultats sur les piliers approvisionnement, production et e-commerce.", "Exclusivement la performance financière à court terme et le cours de bourse.", "Exclusivement la performance financière à court terme et la valeur partenariale."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-71", chapter: 3, difficulte: "difficile", question: "Une entreprise de chimie décide de remplacer un solvant toxique très bon marché par une alternative naturelle écologique beaucoup plus chère, ce qui ampute son bénéfice annuel de 20 %.", choix: ["Elle privilégie la performance commerciale, illustrant les arbitrages inhérents à la performance globale.", "Elle privilégie la performance environnementale, illustrant que les différentes dimensions de la performance globale peuvent nécessiter des arbitrages contradictoires à court terme (baisse de rentabilité au profit de l'écologie).", "Elle pratique un Greenwashing évident pour tromper le consommateur.", "Elle détériore volontairement sa valeur perçue."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-72", chapter: 3, difficulte: "difficile", question: "Un indicateur \"qualitatif\" présent dans un tableau de bord se distingue d'un indicateur \"quantitatif\" car :", choix: ["L'indicateur qualitatif s'exprime toujours en monnaie (ex: le chiffre d'affaires).", "L'indicateur qualitatif mesure une appréciation subjective ou un ressenti (ex: le taux de satisfaction client), tandis que l'indicateur quantitatif mesure un volume chiffré brut (ex: nombre de pièces).", "L'indicateur qualitatif est interdit dans le bilan social de l'entreprise.", "L'indicateur qualitatif mesure un volume chiffré brut (ex: nombre de pièces)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-73", chapter: 3, difficulte: "difficile", question: "Si le chiffre d'affaires d'une entreprise de logistique augmente de 20 % mais que son résultat net (bénéfice) s'effondre de 15 %, l'explication financière logique est que :", choix: ["La valeur perçue par les clients finaux a fortement augmenté.", "Les charges opérationnelles (ex: explosion du prix du carburant) ont progressé moins vite que les ventes.", "Les charges opérationnelles (ex: explosion du prix du carburant) ont progressé beaucoup plus vite que les ventes, écrasant la marge globale générée.", "L'efficience logistique s'est améliorée, libérant de la trésorerie."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-74", chapter: 3, difficulte: "difficile", question: "Une organisation dont la \"rentabilité\" est très faible mais dont la \"liquidité\" (Trésorerie) est jugée excellente :", choix: ["Va faire faillite le mois prochain en cessation de paiements.", "Ne dégage pas de gros profits sur son compte de résultat, mais dispose de suffisamment de cash immédiat sur son compte en banque pour honorer ses dettes à court terme sans difficulté.", "Dégage d'énormes profits mais n'a pas un centime sur son compte bancaire.", "Présente obligatoirement une Marge sur Coût Variable négative sur tous ses produits."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-75", chapter: 3, difficulte: "difficile", question: "L'évaluation de l'activité humaine au travail (lors de l'entretien annuel) est source de tensions managériales potentielles car :", choix: ["Elle est strictement interdite par le RGPD.", "Elle modifie automatiquement la structure de propriété de l'organisation.", "Elle nécessite obligatoirement l'accord formel du représentant de l'État.", "Elle confronte la subjectivité du manager (perception) aux attentes de reconnaissance de l'employé, posant la question épineuse de l'objectivité des critères de performance retenus."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-76", chapter: 4, difficulte: "difficile", question: "L'activité de la station \"SkiMax\" est concentrée sur les mois de décembre à mars, générant 90 % de son chiffre d'affaires annuel. Ce phénomène impose d'intégrer le concept de :", choix: ["Délocalisation stratégique, imposant de gérer des pics de trésorerie.", "Obsolescence technologique, imposant de gérer des pics de trésorerie.", "Saisonnalité, une contrainte temporelle forte imposant de conserver la trésorerie hivernale pour couvrir les charges fixes des mois inactifs en été.", "Saisonnalité, un risque de technologie dépassée."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-77", chapter: 4, difficulte: "difficile", question: "Pour anticiper les évolutions des lois à venir et repérer l'arrivée de nouveaux concurrents, le dirigeant s'abonne à des revues spécialisées et crée des alertes web.", choix: ["Il met en place une démarche de Shadow IT (informatique fantôme).", "Il met en place une politique d'Open Data.", "Il met en place une veille informationnelle, destinée à capter les signaux de l'environnement externe pour réduire l'incertitude.", "Il met en place un tableau de bord rétrospectif."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-78", chapter: 4, difficulte: "difficile", question: "L'équipe du contrôle de gestion construit en novembre le \"budget\" des achats et des ventes pour l'année prochaine.", choix: ["Il s'agit d'un outil rétrospectif, analysant la formation du bénéfice de l'année passée.", "Il s'agit d'un outil rétrospectif, simulant les recettes et les dépenses futures.", "Il s'agit d'un outil prospectif, analysant la formation du bénéfice de l'année passée.", "Il s'agit d'un outil prospectif (tourné vers l'avenir), simulant les recettes et les dépenses pour planifier financièrement l'activité."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-79", chapter: 4, difficulte: "difficile", question: "Une entreprise supporte 100 000 € de charges fixes. Elle vend un produit avec une Marge sur Coût Variable unitaire de 20 € (Prix de vente 50 € - Coût variable 30 €). Son \"seuil de rentabilité\" (volume où le résultat est nul) sera atteint à :", choix: ["2 000 unités, chiffre obtenu en divisant les charges fixes (100k) par le prix de vente (50).", "5 000 unités, car c'est le volume où la Marge sur Coût Variable totale (20 € * 5 000) couvre exactement la totalité des charges fixes (100 000 €).", "100 000 unités, chiffre obligatoirement égal aux charges fixes.", "3 333 unités, chiffre obtenu en divisant les charges fixes par le coût variable unitaire."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-p-ds-80", chapter: 4, difficulte: "difficile", question: "L'apparition foudroyante d'une Intelligence Artificielle générative capable de créer des sites web complets constitue, pour une agence web traditionnelle, un :", choix: ["Risque interne, caractérisé par une dépendance d'approvisionnement.", "Risque externe, caractérisé par une dépendance d'approvisionnement.", "Risque interne, caractérisé par une rupture technologique majeure susceptible de rendre son offre obsolète.", "Risque externe, caractérisé par une rupture technologique majeure (issue de l'environnement) susceptible de rendre son modèle économique obsolète."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-81", chapter: 4, difficulte: "difficile", question: "Un PDG décide de lancer un nouveau produit très novateur sur une simple intuition \"géniale\", refusant obstinément de réaliser une étude de marché. Le produit fait un flop financier total.", choix: ["L'origine de ce risque est un facteur interne (découlant de l'aptitude excessive au risque du dirigeant et de son déni de l'incertitude).", "L'origine de ce risque est un facteur externe (découlant de l'aptitude excessive au risque du dirigeant et de son déni de l'incertitude).", "L'origine de ce risque est un facteur interne (lié à un aléa macro-économique imprévisible).", "L'origine de ce risque est un facteur externe (lié à un aléa macro-économique imprévisible)."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-p-ds-82", chapter: 4, difficulte: "difficile", question: "Une agence immobilière fixe le prix de vente d'un grand immeuble en se basant sur une estimation d'expert datant de quatre ans. L'immeuble ne trouve aucun acheteur. L'erreur de gestion réside dans l'oubli que la valeur de l'information dépend étroitement de :", choix: ["Son caractère gratuit et librement diffusable (Open Data).", "Sa confidentialité absolue.", "Sa source exclusivement interne.", "Son actualité (dimension temporelle) : face aux fluctuations permanentes du marché, une donnée n'est pertinente que si elle est très récente."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-83", chapter: 4, difficulte: "difficile", question: "Dans la planification stratégique, l'allongement de l'horizon prévisionnel (par exemple, prévoir les ventes de voitures sur 15 ans au lieu d'un an) a pour effet inéluctable de :", choix: ["Diminuer le niveau d'incertitude, car les algorithmes mathématiques lissent les variations.", "Diminuer le niveau d'incertitude, car les charges fixes s'annulent.", "Augmenter le niveau d'incertitude, car le temps long multiplie la probabilité d'occurrence d'aléas externes imprévisibles (ruptures technologiques, crises sanitaires) fragilisant les prévisions.", "Augmenter le niveau d'incertitude, car l'Open Data devient obsolète."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-84", chapter: 4, difficulte: "difficile", question: "Une usine d'assemblage en Europe s'arrête brutalement car son unique fournisseur de composants, basé en Asie, subit un séisme majeur détruisant ses usines.", choix: ["Le risque matérialisé est interne, révélant une politique d'obsolescence programmée.", "Le risque matérialisé est interne, révélant une dépendance logistique.", "Le risque matérialisé est externe, révélant une politique d'obsolescence programmée.", "Le risque matérialisé est externe (aléa climatique), mettant en évidence une dangereuse vulnérabilité de dépendance d'approvisionnement de l'organisation."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-85", chapter: 4, difficulte: "difficile", question: "Le chef de projet utilise un diagramme de Gantt (calendrier visuel des tâches). L'utilité principale de cet outil de gestion du temps est de :", choix: ["Calculer le seuil de rentabilité financier global.", "Évaluer l'empreinte carbone des matériaux de construction.", "Garantir la sécurité des données personnelles (RGPD).", "Gérer l'interdépendance des tâches (savoir quelle tâche doit être finie pour démarrer la suivante) afin d'éviter les retards en chaîne bloquant la livraison."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-86", chapter: 4, difficulte: "difficile", question: "Le service commercial, de peur d'être pénalisé sur ses primes de fin d'année, cache délibérément une forte baisse de ses commandes au service production, qui continue de fabriquer à plein régime. Ce dysfonctionnement illustre :", choix: ["Le cycle de vie naturel du produit en phase de maturité.", "La rentabilité de la théorie de l'ajustement mutuel.", "Une asymétrie d'information interne (rétention volontaire), qui fausse la prise de décision globale et dégrade l'efficience de l'entreprise en créant des surstocks.", "Une preuve de l'efficience de la standardisation des résultats."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-p-ds-87", chapter: 4, difficulte: "difficile", question: "Le concept managérial du \"Cycle de vie d'un produit\" (Lancement, Croissance, Maturité, Déclin) montre que la phase de \"Déclin\" expose inéluctablement l'entreprise au risque :", choix: ["De surchauffe logistique face à une demande explosive impossible à satisfaire.", "D'atteindre son seuil de rentabilité de manière trop précipitée.", "De dépendance d'approvisionnement en matières premières rares.", "D'obsolescence de son produit face aux nouvelles attentes du marché, l'obligeant à innover ou à le retirer pour limiter les pertes."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-88", chapter: 4, difficulte: "difficile", question: "En finance, l'adage économique \"un euro encaissé aujourd'hui a plus de valeur qu'un euro encaissé dans cinq ans\" justifie le recours aux techniques :", choix: ["D'inflation des Mégadonnées (Big Data).", "D'obsolescence programmée de la monnaie fiduciaire.", "De financement participatif ouvert (Crowdfunding).", "D'actualisation, reposant sur l'idée qu'une somme disponible immédiatement constitue un coût d'opportunité : elle peut être placée pour rapporter des intérêts, compensant ainsi le temps d'immobilisation et l'inflation."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-89", chapter: 4, difficulte: "difficile", question: "Malgré l'invention historique de l'appareil photo numérique dans ses propres laboratoires, la direction de Kodak a refusé de modifier son modèle économique basé sur la pellicule, menant à sa faillite. Ce désastre stratégique s'explique par :", choix: ["La dépendance logistique envers ses fournisseurs de plastique (risque externe).", "Les contraintes réglementaires trop sévères du RGPD interdisant les photos numériques.", "La flexibilité quantitative externe poussée à l'extrême par les laboratoires.", "Un facteur interne de risque décisionnel : l'incapacité de l'organisation à sortir de sa zone de confort et à se remettre en cause face à une rupture technologique pourtant évidente."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-90", chapter: 4, difficulte: "difficile", question: "Une crise géopolitique majeure fait doubler le prix du baril de pétrole en un mois pour un transporteur routier dont les prix de vente sont fixés par des contrats annuels fermes. Quelle est l'incidence directe sur la gestion ?", choix: ["Un effet d'aubaine augmentant le résultat net de manière inattendue.", "La transformation de ses charges variables en charges fixes.", "L'amélioration automatique du seuil de rentabilité en volume.", "Un effet de ciseau brutal, la hausse de ses charges variables (carburant) non répercutée sur le prix écrasant mécaniquement sa marge d'exploitation."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-91", chapter: 4, difficulte: "difficile", question: "Avant de commercialiser un nouveau modèle, le contrôleur de gestion utilise les fonctionnalités de \"simulation\" (\"Que se passe-t-il si les ventes baissent de 15% ?\") de son tableur Excel. Cet outil permet de :", choix: ["Garantir l'élimination absolue de l'aléa concurrentiel.", "Sécuriser les données personnelles des clients selon les directives du RGPD.", "Publier automatiquement le bilan comptable en Open Data.", "Modéliser divers scénarios prévisionnels pour évaluer l'incidence mathématique de l'incertitude sur la rentabilité future et sécuriser la prise de décision."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-92", chapter: 4, difficulte: "difficile", question: "L'usine d'un fabricant est totalement inondée, arrêtant la production durant deux mois. Quelle est la conséquence économique (perte d'exploitation) la plus grave pour l'organisation ?", choix: ["La perte du chiffre d'affaires, compensée par l'annulation automatique des charges fixes d'usine.", "L'augmentation des charges variables de production liées aux matières premières.", "La diminution de la valeur partenariale avec ses banques de détail.", "La perte du chiffre d'affaires (zéro ventes), lourdement aggravée par le paiement inévitable des charges fixes (loyers, salaires de base, assurances) qui continuent de courir, creusant un lourd déficit."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-93", chapter: 4, difficulte: "difficile", question: "La marque de mode \"Shein\" produit des vêtements très peu chers, portés quelques fois puis jetés, avec une très lourde empreinte carbone (fret aérien). Face à des consommateurs (Génération Z) de plus en plus soucieux du climat, la marque affronte un risque majeur :", choix: ["De dépendance énergétique envers les serveurs du Cloud Computing.", "De rupture technologique liée à l'Intelligence Artificielle générative.", "De sur-actualisation de l'information financière boursière en Asie.", "D'ordre environnemental et réputationnel (bad buzz), pouvant entraîner une évolution de la demande vers des alternatives durables et un rejet commercial pur et simple de la marque."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-94", chapter: 4, difficulte: "difficile", question: "Dans les processus d'anticipation temporelle, la \"prospective\" (le plan stratégique à 15 ans) se distingue de la \"prévision budgétaire\" (le budget de l'année à venir) par le fait que :", choix: ["La prospective chiffre précisément l'exploitation avec des données fiables, tandis que le budget élabore de vastes scénarios qualitatifs face à un environnement très incertain.", "La prospective s'appuie exclusivement sur le Bilan Social de l'entreprise.", "La prospective est réservée à l'administration d'État, le budget aux PME.", "Le budget chiffre précisément l'exploitation financière annuelle, tandis que la prospective élabore de larges scénarios stratégiques qualitatifs pour aider l'organisation à survivre aux incertitudes lointaines (ex: climat, démographie)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-95", chapter: 4, difficulte: "difficile", question: "Pour protéger son entrepôt central contre le risque d'incendie (qui détruirait l'entreprise), le dirigeant souscrit un contrat très couvrant auprès d'une compagnie d'assurance-dommages. La méthode de gestion des risques adoptée est :", choix: ["L'acceptation du risque, l'entreprise décidant de provisionner elle-même ses pertes futures sur ses fonds propres.", "L'évitement du risque, l'entreprise décidant de ne plus stocker de marchandises inflammables.", "La rétention du risque, l'entreprise publiant ses protocoles de sécurité en Open Data.", "Le transfert du risque à un acteur tiers (l'assureur), moyennant le paiement d'une prime, ce qui permet de lisser et de circonscrire l'incidence financière d'un aléa dramatique."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-96", chapter: 4, difficulte: "difficile", question: "Avant de lancer la production d'une nouvelle chaussure au design très clivant, la marque investit dans une vaste \"étude de marché\" quantitative auprès d'un panel de 2 000 consommateurs. Cet outil d'étude vise stratégiquement à :", choix: ["Supprimer le principe d'actualisation financière des capitaux investis.", "Homogénéiser les méthodes de calcul des coûts complets entre les usines.", "Casser la routine managériale en imposant un contrôle par les résultats au département stylisme.", "Réduire l'incertitude quant à l'adéquation de l'offre avec la demande réelle, limitant ainsi le risque d'échec commercial lourd."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-97", chapter: 4, difficulte: "difficile", question: "Une PME a réalisé de forts bénéfices l'année passée. Le DAF décide de placer la trésorerie excédentaire sur un compte à terme rémunéré à 3 % plutôt que de la laisser \"dormir\" sur le compte courant. Il utilise le principe financier :", choix: ["De l'obsolescence technologique naturelle de la monnaie scripturale.", "De la dépendance géopolitique des marchés bancaires européens.", "Du seuil de rentabilité unitaire des produits stockés en entrepôt.", "Du lien indissociable entre le temps et la valeur financière : une trésorerie immobilisée dans le temps constitue un coût d'opportunité et doit générer un rendement (intérêt) face à l'inflation."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-98", chapter: 4, difficulte: "difficile", question: "En gestion de projet industriel (ex: construction d'une usine), si la tâche A (\"couler les fondations\") prend un mois de retard à cause du gel, la tâche B (\"monter les murs\") ne peut pas démarrer, décalant l'inauguration finale. C'est l'illustration de :", choix: ["L'asymétrie d'information volontaire entre le banquier prêteur et le chef de chantier.", "La flexibilité quantitative externe propre aux entreprises de BTP.", "La standardisation des résultats imposée par les logiciels de PGI.", "La gestion complexe de l'incertitude liée à la forte interdépendance temporelle (séquentialité) des tâches au sein d'un processus contraint."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-99", chapter: 4, difficulte: "difficile", question: "Un libraire de province, persuadé d'un futur succès, commande fermement 5 000 exemplaires du dernier prix Goncourt avant les fêtes. Il n'en vend finalement que 1 500. Son stock massif d'invendus plombera lourdement sa trésorerie dès janvier. Ce risque est directement lié à :", choix: ["Un aléa externe d'ordre purement climatique (météo défavorable) couplé à une dépendance technologique.", "L'évolution imprévisible de la législation fiscale régissant la taxe sur les produits culturels.", "L'influence minoritaire exercée par le fournisseur sur la fixation des marges commerciales.", "Un risque interne d'erreur d'anticipation et de prévision budgétaire, figeant des ressources financières vitales dans un stock obsolète."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-p-ds-100", chapter: 4, difficulte: "difficile", question: "En conclusion sur l'enseignement de la gestion des organisations (SDGN), on peut affirmer que le concept de \"prise de risque\" est :", choix: ["Toujours le symptôme alarmant d'une gestion défaillante qu'il faut totalement éradiquer grâce aux algorithmes d'Intelligence Artificielle.", "Une notion théorique strictement réservée aux entreprises du secteur concurrentiel marchand, l'État ne prenant par définition légale aucun risque.", "Un concept purement comptable servant uniquement à déterminer le calcul du seuil de rentabilité annuel.", "Inhérent et consubstantiel à l'acte d'entreprendre : la pérennité et la performance d'une organisation naissent de sa capacité à identifier, évaluer et accepter des risques calculés pour innover et s'adapter aux mutations de l'environnement."] as [string, string, string, string], bonIndex: 3 },
];
